"""Build the local, self-contained HTML/PDF review guide from captured evidence."""
from pathlib import Path
import base64,json,html
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'docs/user-guide'
sections=[]
def add(title,body,figs):sections.append((title,body,figs))
add('Start here', '''<p>GAYBOY turns a Game Boy into a drum machine, piano-roll sequencer and MIDI synthesizer. Start with the native instruments and samples, make a pattern, balance it in the Mixer, then save it.</p><ol><li>Open <b>build/GAYBOY.gb</b> in the project emulator, or run <b>launch-emulator.ps1</b>.</li><li>Press <b>Start</b> to leave the intro. The DRUM roll opens.</li><li>Hold <b>Select</b> and press <b>A</b> to play. Repeat to stop.</li><li>Hold <b>Start</b>, choose a page with Up/Down, then release Start to open it.</li></ol><p>The captured build opens with a prepared drum pattern. Your cartridge save can change what is present. This guide uses Game Boy button names throughout.</p><table><tr><th>Game Boy</th><th>Project desktop SameBoy / PyBoy</th></tr><tr><td>D-pad</td><td>Arrow keys</td></tr><tr><td>A / B</td><td>X / Z</td></tr><tr><td>Start / Select</td><td>Shift / Space</td></tr><tr><td>Restart ROM</td><td>F5</td></tr></table><p>These keys describe the project launchers. Browser and other emulator mappings can differ; use their displayed controls.</p>''', [('01-drum-roll','The initial DRUM roll: instruments run down the left; time runs to the right.')])
add('Find your way around', '''<p>Hold Start to open the page menu. Keep it held while pressing Up/Down; release it on the page you want. The list scrolls and depends on the current page and Experimental Mode.</p><p>Use <b>P1, P2, WAVE1 and NOISE</b> to choose a native instrument. <b>SEQUENCER</b> edits its notes. <b>SEQ SETTINGS</b> changes timing and track defaults. <b>KITS</b> chooses sample drums; <b>DRUMSYNTH</b> shapes synthesized drums. <b>MIXER</b> balances and launches patterns.</p><p>For a first session, leave Experimental Mode off. Its additional instruments and effects are introduced at the end of this guide.</p>''',[('02-page-menu','The held-Start menu, scrolled to kits and storage actions.'),('03-playing','Select+A starts the transport; the playhead shows the current time position.')])
add('Choose and audition a drum kit', '''<ol><li>Hold Start and choose <b>KITS</b>.</li><li>Use Up/Down to highlight AMEN ORIGINAL, TR-808, TR-909, TR-707, LINNDRUM or OBERHEIM DMX.</li><li>Press <b>A</b> to load the highlighted kit. The star moves to the loaded kit.</li><li>Use Left/Right to choose a sample slot and <b>B</b> to hear it.</li><li>Return to SEQUENCER to hear your pattern with the new kit.</li></ol><p>Browsing highlights a kit; A actually loads it. B auditions the <em>loaded</em> kit. Loading a kit keeps the plotted notes.</p><p>The machine kits use slots 1–8: kick, snare, closed/open hats, clap, low/high toms and a kit-specific percussion sound. Slots 9–10 are silent in those kits. Amen uses its original ten sample slots.</p>''',[('04-kits','TR-808 is loaded; the star identifies the active kit.'),('05-kit-loaded','After Down and A, TR-909 is loaded. B auditions the selected kick slot.')])
add('Program the DRUM roll', '''<p>Open DRUM through the sequencer track navigation: hold Select and press Left until DRUM appears. Left visits empty tracks too; Select+Right skips rolls without plotted notes.</p><ol><li>Use Left/Right for the time step and Up/Down for the drum row.</li><li>Tap <b>B</b> to plot a hit at an empty cell or remove an existing hit.</li><li>Hold <b>B</b> with Left/Right to adjust its length; hold B with Up/Down to edit velocity.</li><li>Use <b>Select+A</b> to hear the pattern and stop it again.</li></ol><p>At 16-step zoom, the bottom sliders show velocities for the selected drum row. Longer dark bars are note gates; sample playback normally continues to the end of the sample. Two PCM samples can play together; a third overlapping sample replaces the oldest voice.</p><p><b>NHH / NSN</b> are synthesized noise hi-hat and snare rows. <b>PK</b> is the Pulsekick row. These do not change when you switch sample kits.</p>''',[('01-drum-roll','Sample rows above, NHH/NSN/PK below, and the velocity strip at the bottom.')])
add('Shape synthesized drums', '''<p>Choose <b>DRUMSYNTH</b> from the Start menu. <b>Select</b> cycles HiHat, Snare and PULSEKICK. Use Up/Down to select a parameter, Left/Right to edit it, <b>A</b> to restore its factory value, and <b>B</b> to audition. B+Left/Right makes larger edits.</p><p>HiHat and Snare offer level, clock shift, divisor, metallic character and fall rate. They share the Game Boy noise channel and take priority over the regular Noise instrument.</p><p>PULSEKICK uses Pulse 1. Its pitch, duty, fall rate, sweep and length shape the kick. A kick temporarily takes priority over a P1 note; the underlying P1 patch is preserved.</p>''',[('06-drumsynth','HiHat / Noise 1 controls.'),('08-pulsekick','PULSEKICK / Pulse 1 controls, including sweep direction and length.')])
add('Choose a melodic sound', '''<ol><li>Hold Start and choose <b>P1</b>. This opens the Pulse 1 Tone screen.</li><li>Use Up/Down to select a parameter and Left/Right to change it. Press <b>B</b> to audition; <b>A</b> resets the selected parameter.</li><li>From the first parameter, press <b>Up</b> to wrap to <b>LOAD PRESET</b>, then A.</li><li>Browse sounds with Up/Down and game banks with Left/Right. <b>A</b> loads; <b>B</b> cancels.</li><li>Choose SEQUENCER to draw notes for this instrument.</li></ol><p>Pulse instruments provide duty, volume and hardware envelope controls. Wave1 uses a waveform and hardware wave level. Noise uses shift, width and divisor. Available parameters depend on the instrument.</p><p>Browsing a preset leaves the current sound alone until you press A.</p>''',[('09-pulse-tone','Native Pulse 1 Tone: the GATE percentage controls how long a sequenced note sounds.'),('10-preset-picker','The preset picker shows the game bank and sound list.')])
add('Draw, erase and lengthen notes', '''<p>In a melodic roll, horizontal position is time and vertical position is pitch. The left keyboard marks octaves. Filled bars are notes; the small outline is the cursor.</p><ol><li>Move to an empty cell and tap <b>B</b> to enter a note. Tap B on a note to erase it.</li><li>Hold <b>B</b> and press Right/Left to extend/shorten a note. Starting on an empty cell creates a note and adjusts its end.</li><li>Hold <b>B</b> and press Up/Down to change velocity.</li><li>Hold <b>A</b> on a note and use directions to move it.</li></ol><p>The last edited duration becomes the default for new notes. If a new note is unexpectedly long, shorten it with B+Left or change DURATION in SEQ SETTINGS.</p><p>Move left from the first visible grid cell onto the piano. Up/Down chooses pitch; hold A to audition. B auditions while stopped and records at the playhead while playing. Right returns to the grid.</p>''',[('12-note-entry','Notes entered with B in the Pulse 1 roll.'),('13-note-duration','B+Right changes the selected note length; this session inherited a long duration.')])
add('Zoom, velocity and selection', '''<p><b>Select+Up</b> zooms in; <b>Select+Down</b> zooms out. Views show 8, 16, 24 or 32 steps. Scroll across the roll to reach later steps in a longer pattern.</p><p>The 16-step view includes the velocity strip. Move below the grid to reach it, use Left/Right to choose a slider, and hold B+Up/Down to edit. Up without B returns to the grid. In the top header, the <b>V</b> switch shows/hides the strip; A or B toggles it.</p><p>Hold <b>A</b> on an empty cell and drag a rectangle to select notes. A-drag on a selected note moves the group; B-drag changes its lengths. Tap A on empty space to clear the selection.</p><p>With a selection active, tap Select for <b>COPY / CUT / PASTE</b>; Up/Down chooses, A confirms, B cancels. The Start-menu COPY/PASTE actions copy the current track when there is no selection. Pasting a whole track can replace the destination track, so save useful work first.</p>''',[('14-zoom','The captured 24-step view fits more time on screen than the default 16-step view.')])
add('Set timing and track length', '''<p>Tap <b>Select</b> in the roll to open SEQ SETTINGS, or choose it from the Start menu. Without an active selection, Select returns to the roll.</p><p>Directions choose a setting. Hold <b>B</b> with Up/Down for small edits or Left/Right for changes of ten. Alternatively, <b>A</b> toggles edit mode and Up/Down changes the value.</p><table><tr><th>Setting</th><th>Use</th></tr><tr><td>BPM</td><td>Pattern tempo; shares the Mixer tempo when global tempo is enabled.</td></tr><tr><td>LENGTH</td><td>Current track loop, 1–256 steps. Tracks can have different lengths.</td></tr><tr><td>VELOCITY / DURATION</td><td>Defaults for newly entered notes.</td></tr><tr><td>MUTE</td><td>Silence this track without removing notes.</td></tr><tr><td>BEATS / BEAT UNIT</td><td>Time signature and beat markings.</td></tr><tr><td>ZOOM STEPS / SWING %</td><td>Visible step count and swing timing; 50 is straight.</td></tr></table><p>In the roll header, highlight the far-right length and hold <b>A+Left</b> to halve or <b>A+Right</b> to double it. Shortening a loop preserves notes outside the active length.</p>''',[('15-seq-settings','Pulse 1 timing and defaults. This capture shows a 64-step track and straight swing.')])
add('Mix and launch live patterns', '''<p>Choose MIXER. Use Left/Right to move across channel strips and Up/Down to choose mute (M), solo (S), volume or pan.</p><ul><li><b>A or B</b> toggles M/S. Multiple solos combine; mute takes priority.</li><li>Hold <b>A or B</b> on volume/pan and use Up/Down for small edits, Left/Right for larger edits.</li><li>Scroll beyond DRM for individual sample/noise/Pulsekick mute and solo switches.</li></ul><p>Eight numbered pads hold the live patterns for a song. Move onto a pad: <b>A</b> requests it; <b>B</b> opens it for editing. The active pad is inverted. A queued pad flashes until its launch boundary.</p><p><b>PLAY</b> starts/stops. <b>LAUNCH</b> cycles NOW, 1/8, 1/4, 1/2 and 1/1. Use a division to time the next launch.</p><p>Move Down from PLAY or LAUNCH to <b>TEMPO</b>. A enables a shared tempo; A+Up/Down changes one BPM and A+Left/Right ten. B switches it off. The range is 30–300 BPM.</p><p>Wave instruments and PCM drums share physical wave output. Their simultaneous playback and stereo routing have hardware limits; drums can take priority over wave notes.</p>''',[('16-mixer','Mixer with native channel strips, drum bus, launch mode, global tempo and eight pads.')])
add('Save a pattern and name it', '''<p>Live pads, the saved pattern library, and saved songs serve different purposes. Save a pattern when you want to recall that arrangement into a live pad later.</p><ol><li>Choose <b>SAVE PATTERN</b> from the Start menu.</li><li>Use Up/Down to select an existing entry or <b>NEW PATTERN</b>.</li><li>Press <b>A</b> to open the naming keyboard. Move with the D-pad; A types a character. B deletes. SPC inserts a space; CLR clears the name.</li><li>Choose <b>SAVE</b> on the keyboard and press A to save, or Select to return to the browser and <b>B</b> to save.</li></ol><p>Names allow sixteen characters. Saving to an existing entry replaces it. The FREE footer shows remaining shared cartridge storage; NOT ENOUGH SPACE means the save did not fit.</p><p>Pattern saves include notes, durations, velocities, timing, mix settings, drum kit and instrument tone settings in this build. Experimental Mode itself stays global.</p>''',[('17-save-pattern','The sparse pattern library includes NEW PATTERN and a remaining-space footer.'),('18-name-keyboard','The actual naming keyboard; its SAVE action writes the pattern.')])
add('Load patterns; save and load songs', '''<p><b>LOAD PATTERN:</b> select a library entry with Up/Down and press <b>A</b>. It loads into the current live pad. Save any edits you want to keep before replacing that pad.</p><p><b>SAVE SONG:</b> saves the eight-pad song. Select a destination with Up/Down, A opens the naming keyboard, and B saves from the browser. The NEED line estimates required bytes.</p><p><b>LOAD SONG:</b> select a saved song and press <b>A</b> to load the whole song. <b>B deletes a song</b> from this page. This differs from the pattern Load page.</p><p>The library is shared by songs. Use distinct names and save both reusable patterns and the song when you want both forms of recall. Keep a backup of the emulator cartridge save file before replacing or deleting valuable work.</p><p>These screenshots show the current sparse storage build. Older ROM/save formats may display different slot lists or an import message.</p>''',[('19-load-pattern','Load Pattern recalls the selected entry into the current live pad.'),('21-load-song','Load Song recalls the full song; its B action deletes the selected song.')])
add('Optional experimental instruments', '''<p>Open GLOBAL SETTINGS and press <b>A</b> to enable Experimental Mode. Changing this setting stops playback. Extra software instruments and effect pages become available; the native workflow remains a good starting point.</p><p><b>MONOSYNTH</b> combines two pulses and a wave oscillator on MIDI channel 5. Hold Select+Left/Right to switch PULSE1, PULSE2, WAVE, MOD and EXP.</p><p>Directions select a row and value/depth/phase cell. Hold <b>B+Up/Down</b> to edit by one or <b>B+Left/Right</b> by ten. <b>A</b> toggles one-handed editing. In MOD, choose LFO or ADSR modulation; a nonzero depth on an oscillator parameter applies that modulation.</p><p>Start with a small duty or level depth. EXP includes software engine, filtering, detune and delay options; the effects begin bypassed. The software engine shares the wave output and is deliberately low fidelity. Treat heavy combinations as experiments, especially on original hardware.</p>''',[('23-global-on','Experimental Mode explicitly enabled.'),('24-monosynth','Pulse 1: base value, modulation depth and phase columns.')])
add('Experimental MOD, EXP and MASTURBATE', '''<p><b>MOD:</b> the ADSR checkbox chooses envelope modulation when checked, LFO when unchecked. LFO WAVE and LFO RATE choose its motion; depth is set on each oscillator page. ARP RATE cycles two or more held channel-5 notes.</p><p><b>EXP:</b> choose an engine and effects. For note echo, delay, level and repeats all need nonzero values. Software audio delay is a separate effect from native note echo.</p><p><b>MASTURBATE</b> is the experimental noise/drone laboratory. Select+A toggles a drone, Select+B randomizes, and A toggles parameter editing. Its screen provides a separate performance patch.</p><p>These pages introduce the main experimental controls. Validate a sound at modest volume and save the pattern once it is useful.</p>''',[('27-mono-mod','Monosynth MOD page with ADSR, LFO and arpeggiator settings.'),('28-mono-exp','EXP NATIVE begins with engine and wave-envelope controls.'),('29-masturbate','MASTURBATE stopped, showing its drone and parameter controls.')])
add('MIDI and troubleshooting', '''<p>For external MIDI, connect the Game Boy link port through an Arduinoboy in <b>mGB mode</b>. Default channels 1–4 address Pulse 1, Pulse 2, Wave and Noise. Channel 5 is the mono/poly instrument; Wave2 uses channel 6 when experimental features are available. A desktop emulator needs its own supported MIDI/link bridge; opening the ROM alone does not connect a keyboard.</p><table><tr><th>Symptom</th><th>Check</th></tr><tr><td>No sound</td><td>Start transport with Select+A; check track and drum mutes/solos, mixer volume, sample slots and emulator audio.</td></tr><tr><td>Right skips a track</td><td>Select+Right visits populated rolls. Use Select+Left or the instrument menu to reach an empty one.</td></tr><tr><td>Wrong kit auditions</td><td>Press A to load the highlighted kit. The star marks the loaded one.</td></tr><tr><td>New notes too long</td><td>Check DURATION; the last length edit becomes the new default.</td></tr><tr><td>Select opens a popup</td><td>A note selection is active. Cancel with B or clear it with an empty A tap.</td></tr><tr><td>Save will not fit</td><td>Check FREE/NEED; back up saves before deleting stored work.</td></tr></table>''',[])
manifest=json.loads((OUT/'capture-manifest.json').read_text())
css='''*{box-sizing:border-box}body{margin:0;background:#eaeae7;color:#191919;font:15px/1.5 Arial,sans-serif}main{max-width:940px;margin:auto;background:white}header{padding:60px 55px;background:#171717;color:white}header h1{font-size:54px;letter-spacing:-2px;margin:12px 0}header p{color:#ccc}nav{padding:28px 55px;columns:2}nav a{display:block;color:#303030;margin:6px 0}section{padding:35px 55px;border-top:1px solid #ccc}h2{font-size:29px;line-height:1.15}h3{font-size:16px}p{margin:12px 0}li{margin:7px 0}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:7px;border:1px solid #bbb;text-align:left}th{background:#eee}.figures{display:flex;flex-wrap:wrap;gap:16px;justify-content:center;margin-top:22px}figure{margin:0;max-width:300px;flex:1 1 220px}figure img{width:100%;height:auto;image-rendering:pixelated;border:1px solid #bbb}figcaption{font-size:12px;line-height:1.4;margin-top:7px;color:#444}code{font-size:10px;overflow-wrap:anywhere}@page{size:A4;margin:15mm}@media print{body{background:white;font-size:10pt;line-height:1.4}main{max-width:none}header{padding:35mm 8mm;background:white;color:black;height:235mm}header p{color:#333}nav{display:none}section{break-before:page;border:0;padding:0}h2{font-size:22pt;margin-top:0}figure{max-width:250px;flex:1 1 180px;break-inside:avoid}figcaption{font-size:8pt}table{font-size:9pt}li{margin:5px 0}.figures{gap:14px;margin-top:16px}p{margin:9px 0}}'''
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GAYBOY user guide</title><style>'+css+'</style><main><header><b>GAYBOY / USER GUIDE</b><h1>Make a beat.<br>Shape a sound.<br>Play it live.</h1><p>Illustrated first edition<br>18 October 2026</p><p>Native instruments · Drums · Sequencing · Mixing<br>Pattern and song storage · Experimental instruments</p></header><nav aria-label="Contents">']
for i,(title,_,_) in enumerate(sections):parts.append(f'<a href="#s{i}">{i+1:02} · {html.escape(title)}</a>')
parts.append('</nav>')
for i,(title,body,figs) in enumerate(sections):
 parts.append(f'<section id="s{i}"><h2>{i+1:02} / {html.escape(title)}</h2>'+body.replace('ROMHASH',manifest['sha256']))
 parts.append('<div class="figures">')
 for name,caption in figs:
  data=base64.b64encode((OUT/'screenshots'/f'{name}.png').read_bytes()).decode()
  parts.append(f'<figure><img alt="{html.escape(caption)}" src="data:image/png;base64,{data}"><figcaption>{html.escape(caption)}</figcaption></figure>')
 parts.append('</div></section>')
parts.append('</main></html>');path=OUT/'GAYBOY-user-guide.html';path.write_text(''.join(parts),encoding='utf-8')
with sync_playwright() as pw:
 browser=pw.chromium.launch(channel='chrome',headless=True);page=browser.new_page();page.goto(path.as_uri());page.evaluate('Promise.all(Array.from(document.images).map(i=>i.decode()))')
 assert page.locator('img').count()==sum(len(x[2]) for x in sections)
 page.pdf(path=str(OUT/'GAYBOY-user-guide.pdf'),print_background=True,display_header_footer=True,header_template='<span></span>',footer_template='<div style="width:100%;text-align:center;font-size:8px;color:#666">GAYBOY · USER GUIDE · <span class="pageNumber"></span> / <span class="totalPages"></span></div>')
 browser.close()
print('Built HTML and PDF',flush=True)
